        return dcModel(name, portCount, 'linear', 'physical', {modelId: 'lumped', parameters: {...parameters, resistance},
            elements: [{type: 'resistor', terminals: [1, name === 'mvia' ? 2 : 'g'], resistance}], joins: []}, settings);
